package com.loopers.application.event;import com.loopers.domain.event.*;import com.loopers.infrastructure.event.OutboxJpaRepository;import com.loopers.infrastructure.order.OrderJpaRepository;import com.loopers.utils.DatabaseCleanUp;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.*;import org.springframework.boot.test.context.TestConfiguration;import org.springframework.context.annotation.*;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;import static org.junit.jupiter.api.Assertions.assertThrows;
@SpringBootTest @Import(OutboxCrashWindowTest.Config.class) class OutboxCrashWindowTest{@Autowired OrderOutboxService service;@Autowired OutboxRelay relay;@Autowired OutboxJpaRepository outbox;@Autowired OrderJpaRepository orders;@Autowired ControlledPublisher publisher;@Autowired DatabaseCleanUp cleanup;@AfterEach void clean(){cleanup.truncateAllTables();publisher.reset();}@Test void orderAndOutboxCommitOrRollbackTogether(){service.create("event-ok",135135,1000,false);assertThat(orders.count()).isEqualTo(1);assertThat(outbox.count()).isEqualTo(1);assertThrows(RuntimeException.class,()->service.create("event-rollback",135135,1000,true));assertThat(orders.count()).isEqualTo(1);assertThat(outbox.count()).isEqualTo(1);}@Test void crashAfterAckPublishesTwiceButEffectIsOnce(){OutboxEvent e=service.create("event-1",135135,1000,false);assertThrows(OutboxRelay.CrashAfterPublish.class,()->relay.relay(e.getId(),true));relay.relay(e.getId(),false);assertThat(publisher.deliveries).isEqualTo(2);assertThat(publisher.effects).containsExactly("event-1");assertThat(outbox.findById(e.getId()).orElseThrow().getStatus()).isEqualTo(OutboxEvent.Status.PUBLISHED);}@TestConfiguration static class Config{@Bean @Primary ControlledPublisher publisher(){return new ControlledPublisher();}}static class ControlledPublisher implements OutboxPublisher{int deliveries;Set<String>effects=new HashSet<>();public void publish(String id,String p){deliveries++;effects.add(id);}void reset(){deliveries=0;effects.clear();}}}
